script:
(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const arm = () => {
        document.documentElement.classList.add("rv-js");
        const io = new IntersectionObserver((entries) => {
            for (const entry of entries) {
                if (!entry.isIntersecting) continue;
                entry.target.classList.add("rv-in");
                io.unobserve(entry.target);
            }
        }, { threshold: 0.08, rootMargin: "0px 0px -6% 0px" });
        document.querySelectorAll(".rv-rise").forEach((el) => io.observe(el));

        const ease = (t) => 1 - Math.pow(1 - t, 3);
        const spin = (el) => {
            const raw = el.textContent.trim();
            const target = parseFloat(raw);
            if (!isFinite(target)) return;
            const dec = raw.includes(".") ? 1 : 0;
            const t0 = performance.now();
            const dur = 1400;
            const tick = (now) => {
                const p = Math.min(1, (now - t0) / dur);
                el.textContent = (target * ease(p)).toFixed(dec);
                if (p < 1) requestAnimationFrame(tick);
                else el.textContent = raw;
            };
            requestAnimationFrame(tick);
        };
        const cio = new IntersectionObserver((entries) => {
            for (const entry of entries) {
                if (!entry.isIntersecting) continue;
                spin(entry.target);
                cio.unobserve(entry.target);
            }
        }, { threshold: 0.5 });
        document.querySelectorAll(".rv-count").forEach((el) =>
            cio.observe(el));
    };
    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", arm);
    } else {
        arm();
    }
})();
